import{At as e,Et as t,dt as n,ft as r,lt as i,n as a,ot as o,ut as s}from"./chunks/framework.8UxoGp64.js";var c=JSON.parse(`{"title":"Progress 进度条","description":"","frontmatter":{},"headers":[],"relativePath":"components/progress.md","filePath":"components/progress.md","lastUpdated":1791177194000}`),l={name:`components/progress.md`};function u(a,c,l,u,d,f){let p=e(`XhDemo`);return t(),i(`div`,null,[c[0]||=s(`<h1 id="progress-进度条" tabindex="-1">Progress 进度条 <a class="header-anchor" href="#progress-进度条" aria-label="Permalink to “Progress 进度条”">​</a></h1><p>表示一件事的完成程度，或一个量在已知区间里的位置。线形、环形与仪表盘三种形态；量加上分段、目标与刻度，就是仪表盘与子弹图。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/progress" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/progress.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/progress" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/progress" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/progress.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to “用法”">​</a></h2><p>value 与 max 共同决定百分比</p>`,5),r(p,{src:`progress/01-basic`}),c[1]||=s(`<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to “组件结构”">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;progress&quot;</code>：<strong><code>root</code></strong> · <code>canvas</code> · <code>track</code> · <code>range</code> · <code>buffer</code> · <code>label</code> · <code>threshold</code> · <code>target</code> · <code>scale</code> · <code>scale-tick</code> · <code>scale-label</code> · <code>needle</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to “示例”">​</a></h2><h3 id="配文字说明" tabindex="-1">配文字说明 <a class="header-anchor" href="#配文字说明" aria-label="Permalink to “配文字说明”">​</a></h3><p>进度条自身只绘制轨道与进度，百分比文字由使用者放置</p>`,6),r(p,{src:`progress/02-labelled`}),c[2]||=o(`h3`,{id:`自定义量程`,tabindex:`-1`},[n(`自定义量程 `),o(`a`,{class:`header-anchor`,href:`#自定义量程`,"aria-label":`Permalink to “自定义量程”`},`​`)],-1),c[3]||=o(`p`,null,`max 不是 100 时按 value/max 折算，用于「已完成 3/8 步」这类场景`,-1),r(p,{src:`progress/03-max`}),c[4]||=o(`h3`,{id:`颜色`,tabindex:`-1`},[n(`颜色 `),o(`a`,{class:`header-anchor`,href:`#颜色`,"aria-label":`Permalink to “颜色”`},`​`)],-1),c[5]||=o(`p`,null,`tone 决定进度段用哪族颜色，不写时沿用品牌色`,-1),r(p,{src:`progress/04-tone`}),c[6]||=o(`h3`,{id:`尺寸`,tabindex:`-1`},[n(`尺寸 `),o(`a`,{class:`header-anchor`,href:`#尺寸`,"aria-label":`Permalink to “尺寸”`},`​`)],-1),c[7]||=o(`p`,null,`size 只改变轨道厚度，不写即默认中档`,-1),r(p,{src:`progress/05-size`}),c[8]||=o(`h3`,{id:`自定义外观`,tabindex:`-1`},[n(`自定义外观 `),o(`a`,{class:`header-anchor`,href:`#自定义外观`,"aria-label":`Permalink to “自定义外观”`},`​`)],-1),c[9]||=o(`p`,null,`轨道色、进度段色与轨道厚度各是一个组件令牌，纯色与渐变都可以使用`,-1),r(p,{src:`progress/06-custom-appearance`}),c[10]||=o(`h3`,{id:`环形`,tabindex:`-1`},[n(`环形 `),o(`a`,{class:`header-anchor`,href:`#环形`,"aria-label":`Permalink to “环形”`},`​`)],-1),c[11]||=o(`p`,null,`variant="circle" 把同一份进度绘制为环，尺寸档改变的是直径`,-1),r(p,{src:`progress/07-circle`}),c[12]||=o(`h3`,{id:`缺口`,tabindex:`-1`},[n(`缺口 `),o(`a`,{class:`header-anchor`,href:`#缺口`,"aria-label":`Permalink to “缺口”`},`​`)],-1),c[13]||=o(`p`,null,`variant="dashboard" 在环上留一个缺口，gapDegree 与 gapPosition 决定缺口大小与朝向`,-1),r(p,{src:`progress/08-dashboard`}),c[14]||=o(`h3`,{id:`环心文字`,tabindex:`-1`},[n(`环心文字 `),o(`a`,{class:`header-anchor`,href:`#环心文字`,"aria-label":`Permalink to “环心文字”`},`​`)],-1),c[15]||=o(`p`,null,`组件只负责把内容放置到环心，写什么由使用者决定`,-1),r(p,{src:`progress/09-circle-label`}),c[16]||=o(`h3`,{id:`环的外观`,tabindex:`-1`},[n(`环的外观 `),o(`a`,{class:`header-anchor`,href:`#环的外观`,"aria-label":`Permalink to “环的外观”`},`​`)],-1),c[17]||=o(`p`,null,`直径、颜色与端点经令牌，线宽经 strokeWidth：它改变的是几何，半径随之向内收缩`,-1),r(p,{src:`progress/10-circle-appearance`}),c[18]||=o(`h3`,{id:`仪表盘`,tabindex:`-1`},[n(`仪表盘 `),o(`a`,{class:`header-anchor`,href:`#仪表盘`,"aria-label":`Permalink to “仪表盘”`},`​`)],-1),c[19]||=o(`p`,null,`量（semantics="meter"）的仪表盘：thresholds 画出分段色带，scale 画出量程刻度，indicator 选填充或指针`,-1),r(p,{src:`progress/11-gauge`}),c[20]||=o(`h3`,{id:`子弹图`,tabindex:`-1`},[n(`子弹图 `),o(`a`,{class:`header-anchor`,href:`#子弹图`,"aria-label":`Permalink to “子弹图”`},`​`)],-1),c[21]||=o(`p`,null,`线形的量加上分段与目标：色带是好坏区间，中间一条是实际值，竖线是目标，下方是量程刻度`,-1),r(p,{src:`progress/12-bullet`}),c[22]||=o(`h3`,{id:`分段`,tabindex:`-1`},[n(`分段 `),o(`a`,{class:`header-anchor`,href:`#分段`,"aria-label":`Permalink to “分段”`},`​`)],-1),c[23]||=o(`p`,null,`steps 把轨道切成等宽的格，填充按整格亮起；读屏报的仍是实际值`,-1),r(p,{src:`progress/13-steps`}),c[24]||=o(`h3`,{id:`条纹`,tabindex:`-1`},[n(`条纹 `),o(`a`,{class:`header-anchor`,href:`#条纹`,"aria-label":`Permalink to “条纹”`},`​`)],-1),c[25]||=o(`p`,null,`striped 在填充上铺一层斜纹，进行中沿行向流动，完成后静止；减弱动效下不流动`,-1),r(p,{src:`progress/14-striped`}),c[26]||=o(`h3`,{id:`缓冲`,tabindex:`-1`},[n(`缓冲 `),o(`a`,{class:`header-anchor`,href:`#缓冲`,"aria-label":`Permalink to “缓冲”`},`​`)],-1),c[27]||=o(`p`,null,`buffer 在填充之后画第二段浅色填充，表示已经就绪、还没用到的那一截，如视频已缓冲到的位置`,-1),r(p,{src:`progress/15-buffer`}),c[28]||=s(`<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to “设计指引”">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to “何时使用”">​</a></h3><ul><li>上传、导出、批处理等有确定完成度的过程。</li><li>容量、配额等比例值。</li><li>一个量对照好坏区间或目标值：CPU 占用对照警戒线（仪表盘），本季销售额对照目标（子弹图）。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to “何时不用”">​</a></h3><ul><li>完成度未知时，使用<a href="./spinner">加载指示器</a>或<a href="./loading-bar">加载条</a>的爬升模式。</li><li>表示步骤而不是比例时，使用<a href="./steps">步骤条</a>。</li><li>要看一个量随时间怎么走：使用<a href="./sparkline">迷你图</a>或<a href="./cartesian-chart">直角坐标图</a>，仪表盘只报此刻。</li><li>比较多个量的大小：使用直角坐标图的横向条形图，一排仪表盘难以互相比较。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to “特性”">​</a></h3><ul><li><code>variant</code> 三档：线形、环形、仪表盘；仪表盘的缺口角度与位置可调。</li><li><code>indeterminate</code> 表达进行中但剩余量未知。</li><li><code>valueText</code> 决定读屏读出的内容：“3 个文件中的第 2 个”比“66%”更有用。</li><li>环心可以放置文字。</li><li>线形另有三样外观，写在环形上会报 <code>progress.option-ignored</code> 并按没给处理： <ul><li><code>steps</code> 把轨道切成等宽的格，格间留一道间隙；填充按整格亮起，不足一格的部分不画，读屏报的仍是实际值。取不小于 2 的整数，取值不合法同样报错。</li><li><code>striped</code> 在填充上铺一层斜纹：进行中沿行向流动，完成后静止；减弱动效下始终静止，强制色下退掉斜纹、只留高亮色填充。</li><li><code>buffer</code> 在填充之后画第二段浅色填充，表示已经就绪、还没用到的那一截（视频已缓冲到的位置）。它只属于进度：<code>semantics=&quot;meter&quot;</code> 下报错不画，进度未知时也不画；低于 <code>value</code> 的部分被填充盖住。缓冲段由 Vue 与 React 直接渲染，Web Components 侧由元素生成进 track、排在 range 之前。</li></ul></li><li><code>semantics=&quot;meter&quot;</code> 报告的是量而不是进度：根是 <code>role=&quot;meter&quot;</code>，不接受 <code>indeterminate</code>。量另有四样刻画，在进度语义下写了会报 <code>chart.meter-only</code> 并按没给处理： <ul><li><code>thresholds</code> 分段：按上界升序排列，每段带语气与名字，画成轨道上同族淡色的色带；当前值所在的那一段决定填充色。第一段从 0 起、含 0，其余每段含上界、不含下界，超出最后一段上界的值不属于任何一段、填充取 <code>tone</code>。上界不升序、不是有限数或越出 <code>(0, max]</code> 时报 <code>chart.invalid-range</code>，整组不画。</li><li><code>target</code> 目标值：线形是一道横穿轨道、上下各探出一点的竖线，环形是一道横穿弧的短线。不在 <code>[0, max]</code> 内时报错不画。</li><li><code>scale</code> 量程刻度：<code>true</code> 取缺省（约 5 个刻度），也可以写 <code>{ ticks, format }</code> 指定刻度数量与数字格式；刻度从 0 到满值取好读的步长，刻度值按 <code>locale</code> 写。线形的刻度排在轨道下方，两端的刻度值贴着轨道两端对齐；环形的刻度画在弧的内侧。</li><li><code>indicator=&quot;needle&quot;</code> 只对仪表盘有效：用一根指针指出当前值，弧上的填充收起、只留色带，环心内容让到缺口那一侧；数值变化时指针转动。写在其他形态上会报一条警告并按 <code>fill</code> 处理。</li></ul></li><li>线形加上分段时画成子弹图：轨道加厚一档，填充收窄成中间一条压在色带上，色带在填充两侧照样读得出。</li><li>色带、目标刻度、刻度与指针按数据生成：Vue 与 React 直接渲染，Web Components 侧由元素生成进作者写的外壳（线形在 track 与 root 里，环形在 canvas 与 root 里）；分段与刻度的配置只走 JS property。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to “组合”">​</a></h3><ul><li>与<a href="./statistic">统计数值</a>并排；文件上传的每一项配一条。</li><li>仪表盘的环心放当前值；读数旁写清量的名字与单位。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to “最佳实践”">​</a></h3><ul><li>长任务给出剩余时间或剩余数量，只有百分比难以判断等待时长。</li><li>到 100% 后要有明确的完成态，不停留在满格。</li><li>分段写上名字（「正常」「警戒」）：读屏据此在数值后补上所在的分段，颜色不是唯一线索。</li><li>用 <code>steps</code> 表达「第几步」时同时给 <code>valueText</code>（「第 3 步，共 5 步」），读屏才念得出步数而不是百分比。</li><li>条纹只用来提示「仍在进行」，不拿它区分语气或类别。</li><li>分段的语气只表达好坏；没有好坏之分的区间用同一种语气，不要为了好看换颜色。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to “反模式”">​</a></h3><ul><li>进度倒退。</li><li>用假进度条掩盖未知的等待。</li><li>一页铺满仪表盘：一个仪表盘只报一个此刻的量，多个量的比较交给条形图。</li><li>用进度语义画分段与目标：进度只有完成多少，没有警戒区。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to “API 参考”">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to “产物”">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-progress&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhProgress</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/progress.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to “Props”">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>buffer</code></td><td><code>number</code></td><td></td><td>缓冲值：在填充之后画第二段浅色填充，表示已经就绪、还没用到的那一截（如视频已缓冲到的位置）， 越界夹到 [0, max]，低于 value 的部分被填充盖住。只在进度语义的线形下生效；进度未知时不画。</td></tr><tr><td><code>gapDegree</code></td><td><code>number</code></td><td></td><td>缺口角度，默认 75。只对 dashboard 生效。</td></tr><tr><td><code>gapPosition</code></td><td><code>ProgressGapPosition</code></td><td></td><td>缺口朝向，默认 bottom。只对 dashboard 生效。</td></tr><tr><td><code>indeterminate</code></td><td><code>boolean</code></td><td></td><td>进度未知：进度条改为往复动画，读屏侧不报数。 置真时 aria-valuenow 整体不发出：ARIA 规定不确定进度以该属性缺席表达。</td></tr><tr><td><code>indicator</code></td><td><code>ProgressIndicator</code></td><td></td><td>仪表盘的指示方式，缺省 fill。只在 meter 语义下生效，只对 dashboard 形态有意义。</td></tr><tr><td><code>locale</code></td><td><code>string</code></td><td></td><td>刻度值与读屏文字的语言；未提供时按宿主语言。</td></tr><tr><td><code>max</code></td><td><code>number</code></td><td></td><td>满值上限，默认 100；非有限值或不为正时回退为 100。</td></tr><tr><td><code>scale</code></td><td><code>boolean | ProgressScaleOptions</code></td><td></td><td>量程刻度与刻度值：true 取缺省，也可以给刻度数量与数字格式。只在 meter 语义下生效。</td></tr><tr><td><code>semantics</code></td><td><code>ProgressSemantics</code></td><td></td><td>报告的是进度还是量，默认 progress。meter 档发出 role=&quot;meter&quot;，且 indeterminate 不再生效。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg。线形影响轨道厚度，环形影响直径</td></tr><tr><td><code>steps</code></td><td><code>number</code></td><td></td><td>分段显示：把线形轨道切成这么多等宽的格，格与格之间留一道间隙。填充按整格走，不足一格的部分不画； 读屏报的仍是实际值。取不小于 2 的整数，只对线形生效；取值不合法或写在环形上时报错、按没给处理。</td></tr><tr><td><code>striped</code></td><td><code>boolean</code></td><td></td><td>条纹：填充上铺一层斜纹，进行中沿行向流动，完成后静止；减弱动效下始终静止。只对线形生效。</td></tr><tr><td><code>strokeWidth</code></td><td><code>number</code></td><td></td><td>环的线宽，使用 viewBox 单位（整个环绘制在 100×100 中），默认 6。 只对 circle / dashboard 生效：它修改的是几何（半径随之向内收缩），因此是 prop 而不是令牌； 线形的厚度仍使用 --xh-progress-thickness。</td></tr><tr><td><code>target</code></td><td><code>number</code></td><td></td><td>目标值：画一道目标刻度。只在 meter 语义下生效；不在 [0, max] 内时报错、不画。</td></tr><tr><td><code>thresholds</code></td><td><code>readonly ProgressThreshold[]</code></td><td></td><td>分段：升序的上界，每段带语气与名字，画成轨道上的色带；当前值所在的那一段决定填充色。 只在 meter 语义下生效。上界不升序、不是有限数或落在 (0, max] 之外时报错，整组不画。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，决定使用哪族颜色</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;ProgressTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>value</code></td><td><code>number</code></td><td></td><td>当前进度值，越界会被夹到 [0, max]；非有限值按 0 处理。</td></tr><tr><td><code>valueText</code></td><td><code>string</code></td><td></td><td>读屏播报的文字，覆盖默认的数值播报（进度不是百分比时使用，如「第 3 步，共 8 步」）。</td></tr><tr><td><code>variant</code></td><td><code>ProgressVariant</code></td><td></td><td>形态，默认 line。circle 绘制整环，dashboard 在环上留出一个缺口。</td></tr></tbody></table><h3 id="progressthreshold" tabindex="-1">ProgressThreshold <a class="header-anchor" href="#progressthreshold" aria-label="Permalink to “ProgressThreshold”">​</a></h3><p><code>thresholds</code> 的元素。</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>number</code></td><td>是</td><td>这一段的上界，在 (0, max] 内。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td>是</td><td></td></tr><tr><td><code>label</code></td><td><code>string</code></td><td></td><td>分段的名字（如「警戒」）：当前值落在这一段时并进读屏文字。</td></tr></tbody></table><h3 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to “状态”">​</a></h3><p>公开状态写入 <code>data-state</code>。</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;indeterminate&#39; | &#39;complete&#39; | &#39;loading&#39;</td></tr><tr><td><code>label</code></td><td>&#39;complete&#39; | &#39;loading&#39;</td></tr></tbody></table><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to “connect API”">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>variant</code></td><td><code>ProgressVariant</code></td><td>落定后的形态。</td></tr><tr><td><code>semantics</code></td><td><code>ProgressSemantics</code></td><td>落定后的语义。</td></tr><tr><td><code>ratio</code></td><td><code>number</code></td><td>进度比例，[0,1]。</td></tr><tr><td><code>percent</code></td><td><code>number</code></td><td>进度百分比，取整。</td></tr><tr><td><code>steps</code></td><td><code>number</code></td><td>落定后的分段数：没分段时为 0。</td></tr><tr><td><code>buffer</code></td><td><code>number | null</code></td><td>缓冲值占满值的比例；没有缓冲值或不画缓冲时为 null。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getCanvasProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>承载环的 &lt;svg&gt;；线形不渲染它。</td></tr><tr><td><code>getTrackProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getRangeProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getBufferProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>缓冲段：线形画在轨道里、填充之前；没有缓冲值时带 hidden。</td></tr><tr><td><code>getLabelProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>环心区域：落位归皮肤，内容归作者。线形不使用。</td></tr><tr><td><code>bands</code></td><td><code>readonly ProgressBand[]</code></td><td>分段色带；不在 meter 语义下或没有分段时为空。</td></tr><tr><td><code>ticks</code></td><td><code>readonly ProgressTick[]</code></td><td>量程刻度；没开刻度时为空。</td></tr><tr><td><code>target</code></td><td><code>number | null</code></td><td>目标值占满值的比例；没有目标时为 null。</td></tr><tr><td><code>indicator</code></td><td><code>ProgressIndicator</code></td><td>落定后的指示方式：只有 meter 语义下的 dashboard 才会是 needle。</td></tr><tr><td><code>getThresholdProps</code></td><td><code>(band: ProgressBand) =&gt; T[&#39;element&#39;]</code></td><td>线形画在轨道里、环形画在 canvas 里。</td></tr><tr><td><code>getTargetProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>线形是轨道外的一道竖线，环形是横穿弧的一道短线。</td></tr><tr><td><code>getScaleProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>刻度值的容器：线形排在轨道下方，环形叠在环上。</td></tr><tr><td><code>getScaleTickProps</code></td><td><code>(tick: ProgressTick) =&gt; T[&#39;element&#39;]</code></td><td>线形画在 scale 里，环形画在 canvas 里。</td></tr><tr><td><code>getScaleLabelProps</code></td><td><code>(tick: ProgressTick) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getNeedleProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>仪表盘的指针，画在 canvas 里。</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to “无障碍”">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to “键盘”">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/meter/" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to “ARIA”">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-valuemax</code></td><td>String(max)</td></tr><tr><td><code>root</code></td><td><code>aria-valuemin</code></td><td>&#39;0&#39;</td></tr><tr><td><code>root</code></td><td><code>aria-valuenow</code></td><td>undefined | String(value)</td></tr><tr><td><code>root</code></td><td><code>aria-valuetext</code></td><td>props.valueText</td></tr><tr><td><code>root</code></td><td><code>role</code></td><td>&#39;meter&#39; | &#39;progressbar&#39;</td></tr><tr><td><code>canvas</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>scale</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><ul><li>进度是 <code>role=&quot;progressbar&quot;</code>，量是 <code>role=&quot;meter&quot;</code>；<code>aria-valuenow</code>、<code>aria-valuemin</code>、<code>aria-valuemax</code> 由组件写出，名字由作者写在根上（<code>aria-label</code> 或 <code>aria-labelledby</code>）。</li><li>当前值落在带名字的分段里时，<code>aria-valuetext</code> 写成「百分数, 分段名」（模板是 <code>translations.segmentValueText</code>，缺省英文逗号，按语言改写）；作者给了 <code>valueText</code> 时只念作者那句。</li><li>色带、目标刻度、刻度与指针都是装饰：<code>role=&quot;meter&quot;</code> 的子节点对读屏是表象，刻度值另在 <code>scale</code> 上 <code>aria-hidden</code>。</li><li>强制色下填充取系统高亮色；线形色带退成每段末端的一道分界线，环形色带退掉，分段名仍由读屏文字给出。</li></ul><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to “样式参考”">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to “皮肤”">​</a></h3><p><code>@xihan-ui/styles/progress.css</code> 按 <code>[data-scope=&quot;progress&quot;][data-part=&quot;root&quot;]</code> 部件选择器书写，发布产物以挂载类 <code>.xh-scope-progress</code> 代替其中的 data-scope（特异性相同），位于 <code>xihan.components</code> 与 <code>xihan.motion</code> 层。覆盖样式使用 <code>xihan.overrides</code>，部件选择器照常可用。</p><p><code>forced-colors: active</code> 下另有一套规则：颜色交给系统，边框与状态标记改用系统色关键字。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to “数据属性”">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-banded</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-indicator</code></td><td>&#39;needle&#39; | undefined</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;indeterminate&#39; | &#39;complete&#39; | &#39;loading&#39;</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>root</code></td><td><code>data-variant</code></td><td>props.variant</td></tr><tr><td><code>canvas</code></td><td><code>data-variant</code></td><td>props.variant</td></tr><tr><td><code>track</code></td><td><code>data-stepped</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>range</code></td><td><code>data-empty</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>range</code></td><td><code>data-indicator</code></td><td>&#39;needle&#39; | undefined</td></tr><tr><td><code>range</code></td><td><code>data-striped</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>range</code></td><td><code>data-tone</code></td><td>active?.tone</td></tr><tr><td><code>buffer</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>buffer</code></td><td><code>data-variant</code></td><td>props.variant</td></tr><tr><td><code>label</code></td><td><code>data-indicator</code></td><td>&#39;needle&#39; | undefined</td></tr><tr><td><code>label</code></td><td><code>data-state</code></td><td>&#39;complete&#39; | &#39;loading&#39;</td></tr><tr><td><code>label</code></td><td><code>data-variant</code></td><td>props.variant</td></tr><tr><td><code>threshold</code></td><td><code>data-tone</code></td><td>band.tone</td></tr><tr><td><code>threshold</code></td><td><code>data-variant</code></td><td>props.variant</td></tr><tr><td><code>target</code></td><td><code>data-variant</code></td><td>props.variant</td></tr><tr><td><code>scale</code></td><td><code>data-variant</code></td><td>props.variant</td></tr><tr><td><code>scale-tick</code></td><td><code>data-variant</code></td><td>props.variant</td></tr><tr><td><code>scale-label</code></td><td><code>data-variant</code></td><td>props.variant</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to “CSS 变量”">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；默认来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>默认来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-progress-buffer</code></td><td><code>buffer</code></td><td><code>background</code></td><td><code>default</code></td><td><code>--xh-_tone-subtle-active</code></td><td>progress 的 buffer 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-progress-buffer-radius</code></td><td><code>buffer</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-progress-range-radius</code></td><td>progress 的 buffer 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-progress-indeterminate-duration</code></td><td><code>range</code></td><td><code>animation</code></td><td><code>state=indeterminate</code></td><td><code>--xh-motion-loop-shimmer</code></td><td>progress 的 range 部件 animation 覆盖槽。</td></tr><tr><td><code>--xh-progress-label-fg</code></td><td><code>label</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-default</code></td><td>progress 的 label 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-progress-label-font-size</code></td><td><code>label</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-text-body-size</code></td><td>progress 的 label 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-progress-linecap</code></td><td><code>range</code></td><td><code>stroke-linecap</code></td><td><code>variant=circle</code><br><code>variant=dashboard</code></td><td><code>round</code></td><td>progress 的 range 部件 stroke-linecap 覆盖槽。</td></tr><tr><td><code>--xh-progress-needle-color</code></td><td><code>needle</code></td><td><code>fill</code></td><td><code>default</code></td><td><code>--xh-fg-default</code></td><td>progress 的 needle 部件 fill 覆盖槽。</td></tr><tr><td><code>--xh-progress-range</code></td><td><code>range</code></td><td><code>background</code><br><code>stroke</code></td><td><code>default</code><br><code>variant=circle</code><br><code>variant=dashboard</code></td><td><code>--xh-_tone</code></td><td>progress 的 range 部件 background、stroke 覆盖槽。</td></tr><tr><td><code>--xh-progress-range-radius</code></td><td><code>buffer</code><br><code>range</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-pill</code></td><td>progress 的 buffer、range 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-progress-size</code></td><td><code>root</code></td><td><code>block-size</code><br><code>inline-size</code></td><td><code>size=lg</code><br><code>size=sm</code><br><code>variant=circle</code><br><code>variant=dashboard</code></td><td><code>10rem</code><br><code>5rem</code><br><code>7.5rem</code></td><td>progress 的 root 部件 block-size、inline-size 覆盖槽。</td></tr><tr><td><code>--xh-progress-step-gap</code></td><td><code>track</code></td><td><code>-webkit-mask-image</code><br><code>mask-image</code></td><td><code>stepped</code></td><td><code>--xh-space-0_5</code></td><td>progress 的 track 部件 -webkit-mask-image、mask-image 覆盖槽。</td></tr><tr><td><code>--xh-progress-stripe-color</code></td><td><code>range</code></td><td><code>background-image</code></td><td><code>striped</code></td><td><code>--xh-_tone-active</code></td><td>progress 的 range 部件 background-image 覆盖槽。</td></tr><tr><td><code>--xh-progress-stripe-duration</code></td><td><code>range</code></td><td><code>animation</code></td><td><code>state=loading</code><br><code>striped</code></td><td><code>--xh-motion-loop-shimmer</code></td><td>progress 的 range 部件 animation 覆盖槽。</td></tr><tr><td><code>--xh-progress-stripe-size</code></td><td><code>range</code></td><td><code>background-position</code><br><code>background-size</code></td><td><code>@keyframes xh-progress-stripes</code><br><code>striped</code></td><td><code>--xh-space-4</code></td><td>progress 的 range 部件 background-position、background-size 覆盖槽。</td></tr><tr><td><code>--xh-progress-target-color</code></td><td><code>target</code></td><td><code>background</code><br><code>stroke</code></td><td><code>variant=circle</code><br><code>variant=dashboard</code><br><code>variant=line</code></td><td><code>--xh-fg-default</code></td><td>progress 的 target 部件 background、stroke 覆盖槽。</td></tr><tr><td><code>--xh-progress-target-radius</code></td><td><code>target</code></td><td><code>border-radius</code></td><td><code>variant=line</code></td><td><code>--xh-shape-pill</code></td><td>progress 的 target 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-progress-thickness</code></td><td><code>root</code><br><code>target</code><br><code>track</code></td><td><code>block-size</code></td><td><code>banded</code><br><code>default</code><br><code>size=lg</code><br><code>size=sm</code><br><code>variant=line</code></td><td><code>--xh-space-1</code><br><code>--xh-space-2</code><br><code>--xh-space-3</code><br><code>--xh-space-4</code><br><code>--xh-track-thickness</code></td><td>progress 的 root、target、track 部件 block-size 覆盖槽。</td></tr><tr><td><code>--xh-progress-threshold-color</code></td><td><code>threshold</code></td><td><code>background</code><br><code>stroke</code></td><td><code>variant=circle</code><br><code>variant=dashboard</code><br><code>variant=line</code></td><td><code>--xh-_tone-subtle-active</code></td><td>progress 的 threshold 部件 background、stroke 覆盖槽。</td></tr><tr><td><code>--xh-progress-track</code></td><td><code>track</code></td><td><code>background</code><br><code>stroke</code></td><td><code>default</code><br><code>variant=circle</code><br><code>variant=dashboard</code></td><td><code>--xh-bg-subtle-active</code></td><td>progress 的 track 部件 background、stroke 覆盖槽。</td></tr><tr><td><code>--xh-progress-track-radius</code></td><td><code>track</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-pill</code></td><td>progress 的 track 部件 border-radius 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to “动效”">​</a></h3><p>动效角色：指示与换位 · 循环（见<a href="./../design/motion#角色">动效规范</a>）。</p><p>可覆盖的动效槽：<code>--xh-progress-indeterminate-duration</code> · <code>--xh-progress-stripe-duration</code>。</p><p>关键帧 <code>xh-progress-indeterminate</code> · <code>xh-progress-stripes</code> 随皮肤自带，不引用别处文件里的名字；<code>rotate</code> · <code>stroke-dashoffset</code> · <code>translate</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p><code>prefers-reduced-motion: reduce</code> 下本组件另有降级规则。</p><h3 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to “RTL”">​</a></h3><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像；只认物理方向的量乘 <code>--xh-direction-sign</code> 换向，按就近的 <code>dir</code> 走；另有按 <code>dir</code> 分支的规则。</p>`,52)])}var d=a(l,[[`render`,u]]);export{c as __pageData,d as default};